import{_ as r,C as i,o as t,c as n,a2 as o,b as c,w as s,a as l,E as h,a3 as d}from"./chunks/framework.D1rSJmVq.js";const v=JSON.parse('{"title":"What is Hookshot","description":"Matrix Hookshot connects your Matrix rooms to external services — GitHub, GitLab, JIRA, webhooks, feeds, and more","frontmatter":{"title":"What is Hookshot","description":"Matrix Hookshot connects your Matrix rooms to external services — GitHub, GitLab, JIRA, webhooks, feeds, and more","audience":["evaluator","user","operator","developer","contributor","architect"]},"headers":[],"relativePath":"understand/what-is-hookshot.md","filePath":"understand/what-is-hookshot.md","lastUpdated":1775241615000}'),u={name:"understand/what-is-hookshot.md"};function p(m,e,b,g,k,f){const a=i("Mermaid");return t(),n("div",null,[e[1]||(e[1]=o('<h1 id="what-is-hookshot" tabindex="-1">What is Hookshot <a class="header-anchor" href="#what-is-hookshot" aria-label="Permalink to &quot;What is Hookshot&quot;">​</a></h1><p>Hookshot is a Matrix <a href="https://spec.matrix.org/latest/application-service-api/" target="_blank" rel="noreferrer">application service</a> that connects Matrix rooms to external services. It receives events from services like GitHub, GitLab, and JIRA, and delivers them as messages in Matrix rooms. It accepts commands from Matrix rooms and executes actions on those services.</p><h2 id="where-hookshot-sits" tabindex="-1">Where hookshot sits <a class="header-anchor" href="#where-hookshot-sits" aria-label="Permalink to &quot;Where hookshot sits&quot;">​</a></h2>',3)),(t(),c(d,null,{default:s(()=>[h(a,{id:"mermaid-9",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20subgraph%20External%5B%22External%20Services%22%5D%0A%20%20%20%20%20%20%20%20GH%5B%22GitHub%22%5D%0A%20%20%20%20%20%20%20%20GL%5B%22GitLab%22%5D%0A%20%20%20%20%20%20%20%20JI%5B%22JIRA%22%5D%0A%20%20%20%20%20%20%20%20WH%5B%22Generic%20Webhooks%22%5D%0A%20%20%20%20%20%20%20%20RSS%5B%22RSS%2FAtom%20Feeds%22%5D%0A%20%20%20%20%20%20%20%20FG%5B%22Figma%22%5D%0A%20%20%20%20%20%20%20%20OP%5B%22OpenProject%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20HS%5B%22Matrix%20Homeserver%22%5D%0A%20%20%20%20%20%20%20%20AS%5B%22Appservice%20API%22%5D%0A%20%20%20%20%20%20%20%20RM%5B%22Matrix%20Rooms%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20HK%5B%22Hookshot%22%5D%0A%20%20%20%20%20%20%20%20LIS%5B%22HTTP%20Listener%22%5D%0A%20%20%20%20%20%20%20%20BR%5B%22Bridge%20Core%22%5D%0A%20%20%20%20%20%20%20%20CONN%5B%2215%20Connection%20Types%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20GH%20--%3E%7Cwebhooks%7C%20LIS%0A%20%20%20%20GL%20--%3E%7Cwebhooks%7C%20LIS%0A%20%20%20%20JI%20--%3E%7Cwebhooks%7C%20LIS%0A%20%20%20%20WH%20--%3E%7Cwebhooks%7C%20LIS%0A%20%20%20%20FG%20--%3E%7Cwebhooks%7C%20LIS%0A%20%20%20%20OP%20--%3E%7Cwebhooks%7C%20LIS%0A%20%20%20%20RSS%20-.-%3E%7Cpolling%7C%20CONN%0A%0A%20%20%20%20LIS%20--%3E%20BR%20--%3E%20CONN%0A%20%20%20%20CONN%20%3C--%3E%7Cevents%20%26%20messages%7C%20AS%0A%20%20%20%20AS%20%3C--%3E%20RM%0A%0A%20%20%20%20style%20HK%20fill%3A%23e8f5e9%2Cstroke%3A%23388E3C%0A%20%20%20%20style%20HS%20fill%3A%23e3f2fd%2Cstroke%3A%231976D2%0A%20%20%20%20style%20External%20fill%3A%23fff3e0%2Cstroke%3A%23F57C00%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p>Hookshot registers with a Matrix homeserver (Synapse, Dendrite, Conduit) as an application service. The homeserver forwards room events to hookshot, and hookshot sends messages back through the homeserver&#39;s client-server API.</p><p>External services send webhooks to hookshot&#39;s HTTP listener. Hookshot routes each webhook to the correct Matrix room based on <strong>connections</strong> — the core abstraction.</p><h2 id="the-core-concept-connections" tabindex="-1">The core concept: Connections <a class="header-anchor" href="#the-core-concept-connections" aria-label="Permalink to &quot;The core concept: Connections&quot;">​</a></h2><p>A <strong>connection</strong> binds a Matrix room to an external resource. One room can have multiple connections. One GitHub repo can be connected to multiple rooms.</p><p>Examples:</p><ul><li>Room <code>#backend:example.com</code> connected to <code>github.com/org/backend</code> — receives PR and issue notifications, accepts <code>!gh</code> commands</li><li>Room <code>#alerts:example.com</code> connected to a generic webhook endpoint — receives CI alerts via HTTP POST</li><li>Room <code>#news:example.com</code> connected to an RSS feed — receives new articles</li></ul><p>Connections are stored as <strong>Matrix room state events</strong>. No external database required. When hookshot restarts, it reconstructs all connections from room state.</p><p>See <a href="./event-lifecycle">Event Lifecycle</a> for how events flow through connections.</p><h2 id="what-hookshot-does" tabindex="-1">What hookshot does <a class="header-anchor" href="#what-hookshot-does" aria-label="Permalink to &quot;What hookshot does&quot;">​</a></h2><p><strong>Inbound (external service to Matrix):</strong></p><ul><li>GitHub: PR notifications, issue updates, push summaries, release announcements, workflow status, discussion threads</li><li>GitLab: Merge request events, issue events, pushes, tags, wiki changes, releases</li><li>JIRA: Issue creation and updates, version events</li><li>Generic webhooks: Any HTTP payload, with optional JavaScript transformation</li><li>RSS/Atom: New feed entries</li><li>Figma: File comment notifications</li><li>OpenProject: Work package events</li><li>ChallengeHound: Activity tracking</li></ul><p><strong>Outbound (Matrix to external service):</strong></p><ul><li>Create, close, assign issues (GitHub, GitLab, JIRA, OpenProject)</li><li>Trigger GitHub Actions workflows</li><li>Map emoji reactions to GitHub actions (approve PRs, close issues)</li><li>Forward room messages to external HTTP endpoints (outbound hooks)</li></ul><p><strong>Management:</strong></p><ul><li>Web widget UI for configuring connections in Matrix clients</li><li>REST provisioning API for programmatic management</li><li>Bot commands for setup and administration</li><li>Per-user OAuth for actions that should use the user&#39;s identity</li></ul><h2 id="what-hookshot-is-not" tabindex="-1">What hookshot is NOT <a class="header-anchor" href="#what-hookshot-is-not" aria-label="Permalink to &quot;What hookshot is NOT&quot;">​</a></h2><ul><li><strong>Not a full sync bridge.</strong> Hookshot delivers notifications and accepts commands. It does not mirror entire conversation histories between Matrix and external services.</li><li><strong>Not a generic Matrix bot framework.</strong> Hookshot is specifically designed for service integration. For general-purpose bots, use matrix-bot-sdk directly.</li><li><strong>Not stateless.</strong> Hookshot maintains connection state (via Matrix room state events) and credential state (via an encrypted token store). It needs persistent storage.</li></ul><h2 id="key-numbers" tabindex="-1">Key numbers <a class="header-anchor" href="#key-numbers" aria-label="Permalink to &quot;Key numbers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Metric</th><th>Count</th></tr></thead><tbody><tr><td>External services supported</td><td>8</td></tr><tr><td>Connection types</td><td>15</td></tr><tr><td>Inbound event handler bindings</td><td>45+</td></tr><tr><td>Bot command definitions</td><td>66</td></tr><tr><td>Configuration keys</td><td>35+</td></tr><tr><td>Rust NAPI modules</td><td>8</td></tr></tbody></table><h2 id="technology" tabindex="-1">Technology <a class="header-anchor" href="#technology" aria-label="Permalink to &quot;Technology&quot;">​</a></h2><ul><li><strong>Runtime:</strong> Node.js (TypeScript)</li><li><strong>Performance-critical modules:</strong> Rust via NAPI-rs (feed parsing, token encryption, formatting, permissions)</li><li><strong>Matrix SDK:</strong> matrix-appservice-bridge + matrix-bot-sdk (Element fork)</li><li><strong>Webhook sandbox:</strong> QuickJS (JavaScript transformation functions run in a WASM sandbox)</li><li><strong>Build:</strong> Vite (TypeScript), Cargo (Rust)</li></ul><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><table tabindex="0"><thead><tr><th>I want to...</th><th>Read</th></tr></thead><tbody><tr><td>Understand how events flow through hookshot</td><td><a href="./event-lifecycle">Event Lifecycle</a></td></tr><tr><td>See what each integration can do</td><td><a href="./../integrations/overview">Integration Overview</a></td></tr><tr><td>Try hookshot in 5 minutes</td><td><a href="./../get-started/quickstart">Quickstart</a></td></tr><tr><td>Deploy hookshot to production</td><td><a href="./../guides/operator/installation">Installation Guide</a></td></tr><tr><td>Understand the internal architecture</td><td><a href="./../architecture/connections">Architecture: Connections</a></td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./event-lifecycle">Event Lifecycle</a> — How events flow through the system</li><li><a href="./../integrations/overview">Integration Overview</a> — All services and capabilities</li><li><a href="./../architecture/connections">Architecture: Connections</a> — The Connection abstraction in depth</li><li><a href="https://spec.matrix.org/latest/application-service-api/" target="_blank" rel="noreferrer">Matrix Spec: Application Service API</a> — How hookshot connects to homeservers</li></ul>',25))])}const x=r(u,[["render",p]]);export{v as __pageData,x as default};
